-- A PC without that file gets every monitor at its best mode, placed automatically.
local monitorsFile = os.getenv("HOME") .. "/.config/hypr/monitors.lua"
local monitors = io.open(monitorsFile)
if monitors then
    monitors:close()
    dofile(monitorsFile)
else
    hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })
end

