-- WORKSPACE GLIDE
-- A desktop starts moving on the very first frame and eases into place.
-- Jumping several desktops at once is one continuous glide: the desktops in between pass at a
-- steady speed, and the last one slows down from exactly that speed, so nothing stops and restarts.
-- It all runs inside Hyprland, so there's no script to start between the key press and the motion.
-- At 1 a desktop stops exactly in place. Above 1 it would slide past and spring back.
local GLIDE_BOUNCE = 1
hl.curve("glide", { type = "bezier", points = { {0.2, 0.9}, {0.3, GLIDE_BOUNCE} } })

local GLIDE_MS        = 480 -- one desktop, and the landing of a longer trip
local GLIDE_PASS_MS   = 100 -- each desktop passed on the way
local GLIDE_PASSES_MS = 380 -- the most time spent passing desktops, however many there are

local function glideAnimation(ms, curve)
    if curve == "glide" then
        -- An ordinary switch to the next desktop rides the "settle" spring: quick, no overshoot
        hl.animation({ leaf = "workspaces", enabled = true, speed = ms / 100, spring = "settle", style = "slide" })
    else
        hl.animation({ leaf = "workspaces", enabled = true, speed = ms / 100, bezier = curve, style = "slide" })
    end
end
glideAnimation(GLIDE_MS, "glide")

local function glideFocus(workspace)
    hl.dispatch(hl.dsp.focus({ workspace = workspace }))
end

-- The desktops to visit, in order, and the monitor's frame time in ms.
-- Desktops on another monitor are skipped, because focusing one would pull the cursor over there.
-- A target on another monitor is jumped to directly.
local function glidePath(target)
    local active = hl.get_active_workspace()
    -- Special workspaces have negative ids, so there's nothing to pass through
    if not active or not active.id or active.id < 1 or not active.monitor then
        return { target }, 0
    end
    local frame = math.ceil(1000 / active.monitor.refresh_rate)
    local elsewhere = {}
    for _, workspace in ipairs(hl.get_workspaces()) do
        if workspace.id and workspace.monitor and workspace.monitor.id ~= active.monitor.id then
            elsewhere[workspace.id] = true
        end
    end
    if elsewhere[target] then
        return { target }, frame
    end
    local path = {}
    local step = target > active.id and 1 or -1
    for id = active.id + step, target, step do
        if not elsewhere[id] then
            path[#path + 1] = id
        end
    end
    return path, frame
end

local glideTimer
local glideRun = 0

-- A new key press takes over from a glide that's still running
local function glideAfter(ms, run, callback)
    glideTimer = hl.timer(function()
        if run == glideRun then
            callback()
        end
    end, { timeout = ms, type = "oneshot" })
end

function glide_to_workspace(target)
    glideRun = glideRun + 1
    local run = glideRun
    if glideTimer then
        glideTimer:set_enabled(false)
    end

    local path, frame = glidePath(target)
    if #path < 2 then
        glideAnimation(GLIDE_MS, "glide")
        if path[1] then
            glideFocus(path[1])
        end
        return
    end

    local passes = #path - 1
    local pass = math.floor(math.min(GLIDE_PASS_MS, GLIDE_PASSES_MS / passes))
    -- The landing curve sets off at the speed the desktops were passing at
    local slope = GLIDE_MS / pass
    local x = math.min(0.15, 0.95 / slope)
    hl.curve("glideLanding", { type = "bezier", points = { {x, x * slope}, {0.3, GLIDE_BOUNCE} } })

    local function land()
        glideAnimation(GLIDE_MS, "glideLanding")
        glideFocus(path[#path])
        glideAfter(GLIDE_MS + frame + 1, run, function()
            glideAnimation(GLIDE_MS, "glide")
        end)
    end

    local function passDesktop(i)
        glideFocus(path[i])
        if i < passes then
            glideAfter(pass, run, function() passDesktop(i + 1) end)
        else
            -- One frame later than the rest: a desktop still finishing its pass would
            -- jump back on screen if the animation got longer underneath it
            glideAfter(pass + frame + 1, run, land)
        end
    end

    glideAnimation(pass, "linear")
    passDesktop(1)
end

