-- Keep these at full brightness when unfocused, so you can watch or play on one
-- monitor while the mouse is on the other
hl.window_rule({
    name   = "no-dim-fullscreen",
    match  = { fullscreen = true },
    no_dim = true,
})
hl.window_rule({
    name   = "no-dim-games-and-video",
    match  = { class = "^(steam_app_.*|org\\.vinegarhq\\.sober|robloxplayerbeta\\.exe|robloxstudiobeta\\.exe|mpv|blender)$" },
    no_dim = true,
})

hl.window_rule({
    -- Geometry Dash toggles fullscreen on and off every frame under XWayland.
    -- Ignore its own requests so it can't loop.
    name  = "geometry-dash-fullscreen",
    match = { class = "^steam_app_322170$" },

    suppress_event = "fullscreen maximize",
})

-- suppress_event also blocks fullscreen window rules, so fullscreen it on open instead.
hl.on("window.open", function (window)
    if window.class == "steam_app_322170" then
        hl.dispatch(hl.dsp.window.fullscreen_state({ internal = 2, client = 2, action = "set", window = "class:^steam_app_322170$" }))
    end
end)


