    hl.layer_rule({
        name         = "waybar-glass",
        match        = { namespace = "^waybar$" },
        blur         = true,
        ignore_alpha = 0.05,
    })
end)
pcall(function()
    hl.layer_rule({
        name         = "notifications-glass",
        match        = { namespace = "^(notifications|swaync-notification-window|swaync-control-center)$" },
        blur         = true,
        ignore_alpha = 0.05,
    })
end)
