pcall(function()
    hl.layer_rule({
        name      = "spotlight-pop",
        match     = { namespace = "^(wofi|spotlight)$" },
        animation = "popin 80%",
        dim_around = true,
    })
end)
-- The Control Center is frosted glass, and slides down by itself (so no layer animation).
-- ignore_alpha sits between the panel (0.62) and its drop shadow (under 0.5), so only the panel
-- is frosted. Any lower and the shadow gets blurred too, which shows as a square behind the panel
pcall(function()
    hl.layer_rule({
        name         = "control-center-glass",
        match        = { namespace = "^control-center$" },
        blur         = true,
        ignore_alpha = 0.55,
        no_anim      = true,
    })
end)
-- The overview blurs and darkens everything behind it. It draws its finished picture before it
-- appears, and Hyprland zooms and fades that in here, on the graphics card, so it stays smooth
pcall(function()
    hl.layer_rule({
        name         = "overview-glass",
        match        = { namespace = "^overview$" },
        blur         = true,
        ignore_alpha = 0,
        animation    = "popin 88%",
    })
end)
-- The volume popup (waybar/osd.py) is frosted glass and pops in with a bounce
pcall(function()
    hl.layer_rule({
        name         = "osd-glass",
        match        = { namespace = "^osd$" },
        blur         = true,
        ignore_alpha = 0.3,
        animation    = "popin 70%",
    })
end)
-- The notch animates itself, and Hyprland's layer animation stretches it when it resizes
pcall(function()
    hl.layer_rule({
        name    = "waybar-notch-no-anim",
        match   = { namespace = "^waybar-notch$" },
        no_anim = true,
    })
end)
-- The screenshot flash (screenshot-flash.py) fades by itself
pcall(function()
    hl.layer_rule({
        name    = "screenshot-flash-no-anim",
        match   = { namespace = "^screenshot-flash$" },
        no_anim = true,
    })
end)
-- The screenshot freeze (screenshot.sh) has to appear instantly, not fade in
pcall(function()
    hl.layer_rule({
        name    = "screenshot-freeze-no-anim",
        match   = { namespace = "^hyprpicker$" },
        no_anim = true,
    })
end)


--------------------
---- SCREENSHOT ----
--------------------

-- Super+Shift+S: the screen freezes, then drag to select an area. Saves to ~/Pictures/screenshot and copies to clipboard.
-- Needs: grim slurp wl-clipboard hyprpicker   (Esc cancels the selection; see screenshot.sh)
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd([[sh "$HOME/.config/hypr/screenshot.sh"]]))

-- Insert: save the last 30 seconds of your game monitor (DP-3) to ~/Videos/Clips (see ~/.config/waybar/clips.py)
-- Super+Insert: switch clip recording on or off, same as the switch in the clips panel
-- (it starts off at login, so nothing records until you turn it on)
hl.bind("Insert", hl.dsp.exec_cmd([[python3 "$HOME/.config/waybar/clips.py" --save]]))
hl.bind(mainMod .. " + Insert", hl.dsp.exec_cmd([[python3 "$HOME/.config/waybar/clips.py" --toggle]]))
